{
  "decision-midnight-course-hold-credit": "WITH legs AS (SELECT squad, leg_no, start_s + CASE WHEN start_s < 43200 THEN 86400 ELSE 0 END AS s, finish_s + CASE WHEN finish_s < 43200 THEN 86400 ELSE 0 END AS f FROM leg_log WHERE finish_s IS NOT NULL), hold AS (SELECT begin_s + CASE WHEN begin_s < 43200 THEN 86400 ELSE 0 END AS b, resume_s + CASE WHEN resume_s < 43200 THEN 86400 ELSE 0 END AS r FROM course_hold), credited AS (SELECT squad, leg_no, f - s AS elapsed_s, max(0, min(f, r) - max(s, b)) AS credit_s FROM legs CROSS JOIN hold) SELECT squad, leg_no, credit_s, elapsed_s - credit_s AS adjusted_s FROM credited ORDER BY squad COLLATE BINARY, leg_no",
  "decision-milestone-order-count": "WITH RECURSIVE orders(path) AS (SELECT '' UNION ALL SELECT o.path || m.milestone_id FROM orders AS o CROSS JOIN milestones AS m WHERE instr(o.path, m.milestone_id) = 0 AND NOT EXISTS (SELECT 1 FROM dependencies AS d WHERE d.after_id = m.milestone_id AND instr(o.path, d.before_id) = 0)) SELECT count(*) AS ordering_count FROM orders WHERE length(path) = (SELECT count(*) FROM milestones)",
  "decision-minimize-two-cycle-sensor-drift": "WITH prefixes AS (SELECT a.step_code || b.step_code || c.step_code AS sequence, a.drift_microvolts AS first_drift, a.drift_microvolts + b.drift_microvolts AS second_drift, a.drift_microvolts + b.drift_microvolts + c.drift_microvolts AS cycle_drift FROM calibration_step AS a JOIN calibration_step AS b ON b.step_code <> a.step_code JOIN calibration_step AS c ON c.step_code <> a.step_code AND c.step_code <> b.step_code) SELECT sequence, max(abs(first_drift), abs(second_drift), abs(cycle_drift), abs(cycle_drift + first_drift), abs(cycle_drift + second_drift), abs(cycle_drift + cycle_drift)) AS peak_microvolts FROM prefixes ORDER BY peak_microvolts, sequence COLLATE BINARY LIMIT 1",
  "decision-minimum-maintenance-vertex-cover": "WITH RECURSIVE subsets(mask, size, last_bit) AS (SELECT 0, 0, 0 UNION ALL SELECT s.mask + p.tie_bit, s.size + 1, p.tie_bit FROM subsets AS s JOIN access_points AS p ON p.tie_bit > s.last_bit), best AS (SELECT s.mask FROM subsets AS s WHERE NOT EXISTS (SELECT 1 FROM maintenance_links AS l JOIN access_points AS p ON p.point_name = l.pump_name JOIN access_points AS v ON v.point_name = l.valve_name WHERE (s.mask & (p.tie_bit | v.tie_bit)) = 0) ORDER BY s.size, s.mask LIMIT 1) SELECT p.point_name FROM access_points AS p JOIN best ON (best.mask & p.tie_bit) <> 0 ORDER BY p.tie_bit"
